using System; using System.Collections.Generic; using System.IO; using Newtonsoft.Json.Linq;  namespace Plumber_Game.Services {     /// <summary>     /// Manages translation loading from JSON files with English fallback.     /// Supports English, Russian, and Ukrainian languages.     /// </summary>     public static class TranslationManager     {         private static GameLanguage _currentLanguage = GameLanguage.English;         private static Dictionary<GameLanguage, JObject> _translations = new Dictionary<GameLanguage, JObject>();         private static JObject _englishFallback;         private static bool _initialized = false;          /// <summary>         /// Gets or sets the current language.         /// </summary>         public static GameLanguage CurrentLanguage         {             get => _currentLanguage;             set             {                 _currentLanguage = value;                 SaveLanguagePreference();             }         }          /// <summary>         /// Initializes the translation system by loading all language files.         /// </summary>         public static void Initialize()         {             if (_initialized)                 return;              try             {                 string translationsPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Translations");                  // Load English as fallback                 _englishFallback = LoadLanguageFile(Path.Combine(translationsPath, "English.json"));                 _translations[GameLanguage.English] = _englishFallback;                  // Load other languages                 _translations[GameLanguage.Russian] = LoadLanguageFile(Path.Combine(translationsPath, "Russian.json")) ?? _englishFallback;                 _translations[GameLanguage.Ukrainian] = LoadLanguageFile(Path.Combine(translationsPath, "Ukrainian.json")) ?? _englishFallback;                  // Load saved language preference                 LoadLanguagePreference();                  _initialized = true;             }             catch (Exception ex)             {                 System.Diagnostics.Debug.WriteLine($"Translation initialization error: {ex.Message}");                 _initialized = false;             }         }          /// <summary>         /// Gets a translation string by path (e.g., "menu.playGame").         /// Returns English text as fallback if not found.         /// </summary>         public static string Get(string path)         {             if (!_initialized)                 Initialize();              try             {                 // Try current language                 if (_translations.ContainsKey(_currentLanguage))                 {                     var value = _translations[_currentLanguage].SelectToken(path);                     if (value != null && !string.IsNullOrEmpty(value.ToString()))                         return value.ToString();                 }                  // Fallback to English                 if (_englishFallback != null)                 {                     var fallbackValue = _englishFallback.SelectToken(path);                     if (fallbackValue != null)                         return fallbackValue.ToString();                 }                  // Return path as placeholder if nothing found                 return $"[{path}]";             }             catch (Exception ex)             {                 System.Diagnostics.Debug.WriteLine($"Translation error for path '{path}': {ex.Message}");                 return $"[{path}]";             }         }          /// <summary>         /// Gets the language name in the current language.         /// </summary>         public static string GetLanguageName(GameLanguage language)         {             if (language == GameLanguage.English)                 return Get("languages.english") ?? "English";             if (language == GameLanguage.Russian)                 return Get("languages.russian") ?? "???????";             if (language == GameLanguage.Ukrainian)                 return Get("languages.ukrainian") ?? "??????????";             return "English";         }          /// <summary>         /// Gets all available language names for display.         /// </summary>         public static string[] GetAllLanguageNames()         {             return new[]             {                 GetLanguageName(GameLanguage.English),                 GetLanguageName(GameLanguage.Russian),                 GetLanguageName(GameLanguage.Ukrainian)             };         }          private static JObject LoadLanguageFile(string filePath)         {             try             {                 if (!File.Exists(filePath))                 {                     System.Diagnostics.Debug.WriteLine($"Translation file not found: {filePath}");                     return null;                 }                  string json = File.ReadAllText(filePath);                 return JObject.Parse(json);             }             catch (Exception ex)             {                 System.Diagnostics.Debug.WriteLine($"Error loading translation file '{filePath}': {ex.Message}");                 return null;             }         }          private static void SaveLanguagePreference()         {             try             {                 Properties.Settings.Default["GameLanguage"] = _currentLanguage.ToString();                 Properties.Settings.Default.Save();             }             catch { }         }          private static void LoadLanguagePreference()         {             try             {                 string saved = Properties.Settings.Default["GameLanguage"] as string;                 if (!string.IsNullOrEmpty(saved) && Enum.TryParse<GameLanguage>(saved, out var language))                 {                     _currentLanguage = language;                 }             }             catch { }         }     } } 